import React, { useEffect, useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import api from '../services/api';

const ProductDetail = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const [product, setProduct] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(false);

  useEffect(() => {
    const fetchProduct = async () => {
      try {
        const res = await api.get(`products/${id}/`);
        setProduct(res.data);
      } catch (err) {
        console.error('Ошибка загрузки товара', err);
        setError(true);
      } finally {
        setLoading(false);
      }
    };

    fetchProduct();
  }, [id]);

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '50px', color: '#666' }}>Загрузка информации о товаре...</div>;
  }

  if (error || !product) {
    return (
      <div style={{ textAlign: 'center', padding: '50px' }}>
        <h3>Товар не найден</h3>
        <button onClick={() => navigate('/catalog')} style={{ marginTop: '15px', padding: '8px 16px', background: '#007bff', color: '#fff', border: 'none', borderRadius: '4px', cursor: 'pointer' }}>
          Вернуться в каталог
        </button>
      </div>
    );
  }

  return (
    <div style={{ maxWidth: '800px', margin: '40px auto', padding: '30px', background: '#fff', borderRadius: '12px', boxShadow: '0 4px 12px rgba(0,0,0,0.05)', border: '1px solid #e0e0e0' }}>
      <button 
        onClick={() => navigate(-1)} 
        style={{ background: 'none', border: 'none', color: '#007bff', cursor: 'pointer', marginBottom: '20px', padding: 0, fontSize: '15px' }}
      >
        ← Назад к списку
      </button>

      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: '20px' }}>
        <h1 style={{ margin: 0, fontSize: '28px', color: '#212529' }}>{product.title}</h1>
        <span style={{ fontSize: '24px', fontWeight: 'bold', color: '#28a745' }}>{product.price} ₾</span>
      </div>

      <div style={{ marginBottom: '20px' }}>
        <span style={{ background: '#e9ecef', color: '#495057', padding: '4px 10px', borderRadius: '20px', fontSize: '14px', fontWeight: '500' }}>
          Категория: {product.category_name || 'Без категории'}
        </span>
      </div>

      <div style={{ marginBottom: '30px', borderTop: '1px solid #f1f3f5', borderBottom: '1px solid #f1f3f5', padding: '20px 0' }}>
        <h3 style={{ fontSize: '16px', marginBottom: '10px', color: '#495057' }}>Описание товара</h3>
        <p style={{ fontSize: '16px', lineHeight: '1.6', color: '#6c757d', whiteSpace: 'pre-line', margin: 0 }}>
          {product.description}
        </p>
      </div>

      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', fontSize: '14px', color: '#adb5bd' }}>
        <div>
          <span>Продавец: </span>
          <strong style={{ color: '#495057' }}>{product.owner?.username || 'Не указан'}</strong>
        </div>
        <div>
          <span>Дата публикации: </span>
          <span>{new Date(product.created_at).toLocaleDateString()}</span>
        </div>
      </div>
    </div>
  );
};

export default ProductDetail;
